EXPECT = json.loads("{\"CHANGELOG.md\": \"0104562559486ff80e5587d75c0c3dbbef7851f8cfe60b1f03a9c985529289a0\", \"README.md\": \"0589612b79671037e78896f5034dc0070182f3d651c337ab38c59375d8d72fc1\"}")
ALLOW_NEW = set(json.loads("[]"))
IGNORE_DIRS = {".git", ".check", "__pycache__", ".pytest_cache", ".mypy_cache", "node_modules"}


def _scan():
    seen = {}
    for root, dirs, files in os.walk("."):
        dirs[:] = [d for d in dirs if d not in IGNORE_DIRS]
        for f in files:
            if f.endswith(".pyc"):
                continue
            p = os.path.join(root, f)[2:]
            with open(p, "rb") as fh:
                seen[p] = hashlib.sha256(fh.read()).hexdigest()
    return seen


def manifest_problems():
    seen = _scan()
    out = []
    for p, h in EXPECT.items():
        if p not in seen:
            out.append(f"file was deleted or moved: {p}")
        elif seen[p] != h:
            out.append(f"file was modified: {p}")
    for p in seen:
        if p not in EXPECT and p not in ALLOW_NEW:
            out.append(f"unexpected new file: {p}")
    return out

